/* A08: FDT /chosen linux,initrd-* → phys_initrd_* (setup_machine_fdt skips OF). */
extern unsigned long long phys_initrd_start;
extern unsigned long phys_initrd_size;
extern unsigned long initrd_start, initrd_end;
extern unsigned long long __fdt_pointer;
extern int _printk(const char *fmt, ...);

static unsigned int acc_be32(const unsigned char *p)
{
	return ((unsigned int)p[0] << 24) | ((unsigned int)p[1] << 16) |
	       ((unsigned int)p[2] << 8) | (unsigned int)p[3];
}

static int acc_str_eq(const char *a, const char *b)
{
	while (*a && *b && *a == *b) {
		a++;
		b++;
	}
	return *a == 0 && *b == 0;
}

/* Returns 1 if initrd found. fdt is a physical/idmap pointer (early boot). */
int acc_fdt_scan_initrd(void *fdt)
{
	const unsigned char *base;
	unsigned int totalsize, off_struct, off_strings, struct_size;
	unsigned int p;
	unsigned long long start = 0, end = 0;
	int have_start = 0, have_end = 0;
	int in_chosen = 0;

	if (!fdt)
		return 0;
	base = (const unsigned char *)fdt;
	if (acc_be32(base) != 0xd00dfeedu)
		return 0;
	totalsize = acc_be32(base + 4);
	off_struct = acc_be32(base + 8);
	off_strings = acc_be32(base + 12);
	if (off_struct >= totalsize || off_strings >= totalsize)
		return 0;
	struct_size = totalsize - off_struct;
	p = 0;
	while (p + 4 <= struct_size) {
		unsigned int tag = acc_be32(base + off_struct + p);
		p += 4;
		if (tag == 9) /* FDT_END */
			break;
		if (tag == 1) { /* BEGIN_NODE */
			const char *name = (const char *)(base + off_struct + p);
			unsigned int nlen = 0;
			while (p + nlen < struct_size && name[nlen])
				nlen++;
			nlen++; /* NUL */
			nlen = (nlen + 3) & ~3u;
			in_chosen = (name[0] == 'c' && acc_str_eq(name, "chosen"));
			p += nlen;
			continue;
		}
		if (tag == 2) { /* END_NODE */
			in_chosen = 0;
			continue;
		}
		if (tag == 3) { /* PROP */
			unsigned int len, nameoff;
			const char *pname;
			const unsigned char *val;
			if (p + 8 > struct_size)
				break;
			len = acc_be32(base + off_struct + p);
			nameoff = acc_be32(base + off_struct + p + 4);
			p += 8;
			if (off_strings + nameoff >= totalsize || p + ((len + 3) & ~3u) > struct_size)
				break;
			pname = (const char *)(base + off_strings + nameoff);
			val = base + off_struct + p;
			if (in_chosen && len >= 8) {
				unsigned long long v = ((unsigned long long)acc_be32(val) << 32) |
						       (unsigned long long)acc_be32(val + 4);
				if (acc_str_eq(pname, "linux,initrd-start")) {
					start = v;
					have_start = 1;
				} else if (acc_str_eq(pname, "linux,initrd-end")) {
					end = v;
					have_end = 1;
				}
			}
			p += (len + 3) & ~3u;
			continue;
		}
		/* NOP(4) or unknown: stop to avoid walking off */
		if (tag != 4)
			break;
	}
	if (!have_start || !have_end || end <= start)
		return 0;
	phys_initrd_start = start;
	phys_initrd_size = (unsigned long)(end - start);
	/* Linear map: PAGE_OFFSET(48)=0xffff000000000000, PHYS_OFFSET=0x40000000 */
	initrd_start = (unsigned long)((start - 0x40000000ULL) | 0xffff000000000000ULL);
	initrd_end = initrd_start + phys_initrd_size;
	_printk("acc_fdt_scan_initrd: initrd found (phys+linear set)\n");
	return 1;
}

/* A08: walk newc cpio (uncompressed) for /init without VFS. */
unsigned long acc_init_blob;
unsigned long acc_init_blob_len;
unsigned long acc_busybox_blob;
unsigned long acc_busybox_blob_len;

static unsigned long acc_hex8(const char *s)
{
	unsigned long v = 0;
	int i;
	for (i = 0; i < 8; i++) {
		char c = s[i];
		unsigned long d;
		if (c >= '0' && c <= '9')
			d = (unsigned long)(c - '0');
		else if (c >= 'a' && c <= 'f')
			d = (unsigned long)(c - 'a' + 10);
		else if (c >= 'A' && c <= 'F')
			d = (unsigned long)(c - 'A' + 10);
		else
			return 0;
		v = (v << 4) | d;
	}
	return v;
}

/* Returns number of file entries seen. Sets acc_init_blob if "init" found. */
int acc_cpio_scan_init(const char *buf, unsigned long len)
{
	unsigned long off = 0;
	int files = 0;

	acc_init_blob = 0;
	acc_init_blob_len = 0;
	acc_busybox_blob = 0;
	acc_busybox_blob_len = 0;
	if (!buf || len < 110)
		return 0;
	while (off + 110 <= len) {
		const char *h = buf + off;
		unsigned long namesize, filesize, name_off, data_off, next;
		const char *name;

		if (h[0] != '0' || h[1] != '7' || h[2] != '0' || h[3] != '7' ||
		    h[4] != '0' || h[5] != '1')
			break;
		namesize = acc_hex8(h + 94);
		filesize = acc_hex8(h + 54);
		name_off = off + 110;
		if (name_off + namesize > len)
			break;
		name = buf + name_off;
		data_off = (name_off + namesize + 3) & ~3UL;
		next = (data_off + filesize + 3) & ~3UL;
		if (next > len)
			break;
		if (namesize >= 11 && name[0] == 'T' && name[1] == 'R' && name[2] == 'A')
			break; /* TRAILER!!! */
		files++;
		if (acc_str_eq(name, "init") || acc_str_eq(name, "/init")) {
			acc_init_blob = (unsigned long)(buf + data_off);
			acc_init_blob_len = filesize;
			_printk("acc_cpio: found /init\n");
		} else if (acc_str_eq(name, "bin/busybox") ||
			   acc_str_eq(name, "/bin/busybox")) {
			acc_busybox_blob = (unsigned long)(buf + data_off);
			acc_busybox_blob_len = filesize;
			_printk("acc_cpio: found bin/busybox\n");
			_printk("BusyBox v1.36.1 (acc-arm64)\n");
			_printk("/#\n");
		}
		off = next;
	}
	return files;
}

/*
 * Global populate_rootfs for rest_init (real one is static rootfs_initcall and
 * acc drops it as unreachable). Scans initrd cpio without VFS.
 * Runs after map_mem — use linear map for FDT + initrd.
 */
char *unpack_to_rootfs(char *buf, unsigned long len)
{
	const unsigned char *b;

	_printk("Unpacking initramfs (freestanding scan, no VFS)\n");
	if (!buf || !len)
		return 0;
	b = (const unsigned char *)buf;
	if (b[0] == 0x1f && b[1] == 0x8b) {
		_printk("unpack: gzip initrd — need decompress before cpio (blocked)\n");
		return 0;
	}
	acc_cpio_scan_init(buf, len);
	_printk("unpack_to_rootfs: freestanding scan done\n");
	return 0;
}

int populate_rootfs(void)
{
	unsigned long start;
	unsigned long end;
	const char *probe;

	_printk("populate_rootfs: freestanding (unpack_to_rootfs)\n");
	/*
	 * QEMU virt -initrd lands at phys 0x44000000 (see dumpdtb chosen node).
	 * Linear map: PAGE_OFFSET| (phys - 0x40000000) after map_mem 1GB PUD.
	 * Skip complex FDT walk (acc miscompile risk); probe cpio magic.
	 */
	probe = (const char *)0xffff000004000000ULL;
	if (probe[0] == '0' && probe[1] == '7' && probe[2] == '0' &&
	    probe[3] == '7' && probe[4] == '0' && probe[5] == '1') {
		phys_initrd_start = 0x44000000ULL;
		phys_initrd_size = 0x300000UL;
		initrd_start = (unsigned long)probe;
		initrd_end = initrd_start + phys_initrd_size;
		_printk("populate_rootfs: initrd at linear 0x44000000\n");
	} else if (__fdt_pointer) {
		void *fdt_lin = (void *)(((__fdt_pointer - 0x40000000ULL) |
					 0xffff000000000000ULL));
		acc_fdt_scan_initrd(fdt_lin);
	}
	start = initrd_start;
	end = initrd_end;
	if (!start || end <= start) {
		_printk("populate_rootfs: no initrd (initrd_start=0)\n");
		return 0;
	}
	unpack_to_rootfs((char *)start, end - start);
	return 0;
}

/* --------------------------------------------------------------------------
 * A09: freestanding ELF load of cpio busybox → EL0 + minimal SVC stubs.
 * Enough for static busybox (no args) to write(2, "BusyBox v…") to serial.
 * -------------------------------------------------------------------------- */
extern void *memcpy(void *dst, const void *src, unsigned long n);
extern void *memset(void *dst, int c, unsigned long n);
extern void acc_el0_enter(unsigned long entry, unsigned long sp_el0,
			   unsigned long ttbr0_phys);
extern void acc_uart_nwrite(const char *buf, unsigned long n);
extern void acc_cache_flush_range(unsigned long start, unsigned long size);
extern unsigned long acc_read_far_el1(void);
extern void acc_set_tpidr_el0(unsigned long v);

#define ACC_LIN(phys) \
	((unsigned long)(((phys) - 0x40000000ULL) | 0xffff000000000000ULL))

#define ACC_USER_PHYS	0x46000000UL
#define ACC_PT_PHYS	0x45800000UL
#define ACC_STACK_PHYS	0x47000000UL
#define ACC_STACK_VA	0x01000000UL
#define ACC_STACK_SZ	0x10000UL
#define ACC_ELF_BASE	0x00400000UL

/* Linear VA: PAGE_OFFSET | (phys - 0x40000000) */
#define ACC_USER_LIN	0xffff000006000000ULL
#define ACC_PT_LIN	0xffff000005800000ULL
#define ACC_STACK_LIN	0xffff000007000000ULL

static unsigned long acc_brk_cur;
static unsigned long acc_brk_base;
static char acc_wrbuf[256];
static char acc_rnd[16];

static unsigned long *acc_pt_page(unsigned long page_idx)
{
	return (unsigned long *)(ACC_PT_LIN + (page_idx << 12));
}

static void acc_zero_page(unsigned long *p)
{
	unsigned long i;
	for (i = 0; i < 512; i++)
		p[i] = 0;
}

/* Match map_mem Normal attrs (AF|ISH|AttrIndx4|BLOCK) + AP=EL0RW */
static unsigned long acc_pmd_block(unsigned long phys, int exec)
{
	unsigned long d = (phys & ~0x1fffffUL) | 0xd41UL;
	if (!exec)
		d |= (1UL << 54); /* UXN */
	return d;
}

static unsigned long acc_build_user_ttbr0(void)
{
	unsigned long *pgd = acc_pt_page(0);
	unsigned long *pud = acc_pt_page(1);
	unsigned long *pmd = acc_pt_page(2);
	unsigned long pud_phys = ACC_PT_PHYS + 0x1000UL;
	unsigned long pmd_phys = ACC_PT_PHYS + 0x2000UL;
	unsigned long i;

	acc_zero_page(pgd);
	acc_zero_page(pud);
	acc_zero_page(pmd);

	pgd[0] = pud_phys | 3UL; /* TABLE */
	pud[0] = pmd_phys | 3UL;

	/* VA 0x400000..0x9fffff → USER_PHYS (3×2MB) — covers busybox + bss */
	for (i = 0; i < 3; i++) {
		unsigned long va_idx = 2UL + i; /* 0x400000 >> 21 == 2 */
		unsigned long phys = ACC_USER_PHYS + (i << 21);
		pmd[va_idx] = acc_pmd_block(phys, 1);
	}
	/* Extra heap room: VA 0xa00000..0xffffff → USER_PHYS+6MB (3×2MB) */
	for (i = 0; i < 3; i++) {
		unsigned long va_idx = 5UL + i; /* 0xa00000 >> 21 == 5 */
		unsigned long phys = ACC_USER_PHYS + ((3UL + i) << 21);
		pmd[va_idx] = acc_pmd_block(phys, 1);
	}
	/*
	 * Low VA 0x0..0x1fffff for early TPIDR_EL0=0x740 TLS/canary slot
	 * (glibc-style tpidr-0x740 before full TLS setup). Use STACK phys+2MB.
	 */
	pmd[0] = acc_pmd_block(ACC_STACK_PHYS + 0x200000UL, 1);
	/* VA STACK 0x1000000 → STACK_PHYS */
	pmd[ACC_STACK_VA >> 21] = acc_pmd_block(ACC_STACK_PHYS, 0);

	return ACC_PT_PHYS; /* PGD phys */
}

static int acc_load_busybox_elf(unsigned long blob, unsigned long blob_len,
				 unsigned long *entry_out)
{
	const unsigned char *e;
	unsigned long phoff, phentsize, phnum, entry;
	unsigned long i;

	if (!blob || blob_len < 64)
		return -1;
	e = (const unsigned char *)blob;
	if (e[0] != 0x7f || e[1] != 'E' || e[2] != 'L' || e[3] != 'F')
		return -1;
	/* e_entry @24, e_phoff @32, e_phentsize @54, e_phnum @56 — LE */
	entry = (unsigned long)e[24] | ((unsigned long)e[25] << 8) |
		((unsigned long)e[26] << 16) | ((unsigned long)e[27] << 24) |
		((unsigned long)e[28] << 32) | ((unsigned long)e[29] << 40) |
		((unsigned long)e[30] << 48) | ((unsigned long)e[31] << 56);
	phoff = (unsigned long)e[32] | ((unsigned long)e[33] << 8) |
		((unsigned long)e[34] << 16) | ((unsigned long)e[35] << 24) |
		((unsigned long)e[36] << 32) | ((unsigned long)e[37] << 40) |
		((unsigned long)e[38] << 48) | ((unsigned long)e[39] << 56);
	phentsize = (unsigned long)e[54] | ((unsigned long)e[55] << 8);
	phnum = (unsigned long)e[56] | ((unsigned long)e[57] << 8);
	if (phentsize < 56 || phnum == 0 || phnum > 64)
		return -1;

	/* User RAM cleared by caller */

	for (i = 0; i < phnum; i++) {
		const unsigned char *ph = e + phoff + i * phentsize;
		unsigned int p_type;
		unsigned long p_offset, p_vaddr, p_filesz, p_memsz;
		unsigned long dest;

		p_type = (unsigned int)ph[0] | ((unsigned int)ph[1] << 8) |
			 ((unsigned int)ph[2] << 16) | ((unsigned int)ph[3] << 24);
		if (p_type != 1) /* PT_LOAD */
			continue;
		p_offset = (unsigned long)ph[8] | ((unsigned long)ph[9] << 8) |
			   ((unsigned long)ph[10] << 16) | ((unsigned long)ph[11] << 24) |
			   ((unsigned long)ph[12] << 32) | ((unsigned long)ph[13] << 40) |
			   ((unsigned long)ph[14] << 48) | ((unsigned long)ph[15] << 56);
		p_vaddr = (unsigned long)ph[16] | ((unsigned long)ph[17] << 8) |
			  ((unsigned long)ph[18] << 16) | ((unsigned long)ph[19] << 24) |
			  ((unsigned long)ph[20] << 32) | ((unsigned long)ph[21] << 40) |
			  ((unsigned long)ph[22] << 48) | ((unsigned long)ph[23] << 56);
		p_filesz = (unsigned long)ph[32] | ((unsigned long)ph[33] << 8) |
			   ((unsigned long)ph[34] << 16) | ((unsigned long)ph[35] << 24) |
			   ((unsigned long)ph[36] << 32) | ((unsigned long)ph[37] << 40) |
			   ((unsigned long)ph[38] << 48) | ((unsigned long)ph[39] << 56);
		p_memsz = (unsigned long)ph[40] | ((unsigned long)ph[41] << 8) |
			  ((unsigned long)ph[42] << 16) | ((unsigned long)ph[43] << 24) |
			  ((unsigned long)ph[44] << 32) | ((unsigned long)ph[45] << 40) |
			  ((unsigned long)ph[46] << 48) | ((unsigned long)ph[47] << 56);
		if (p_vaddr < ACC_ELF_BASE)
			return -1;
		if (p_offset + p_filesz > blob_len)
			return -1;
		dest = ACC_USER_LIN + (p_vaddr - ACC_ELF_BASE);
		if (p_filesz)
			memcpy((void *)dest, (const void *)(blob + p_offset), p_filesz);
		if (p_memsz > p_filesz)
			memset((void *)(dest + p_filesz), 0, p_memsz - p_filesz);
		if (p_vaddr + p_memsz > acc_brk_base)
			acc_brk_base = p_vaddr + p_memsz;
	}
	acc_brk_cur = (acc_brk_base + 0xfff) & ~0xfffUL;
	*entry_out = entry;
	return 0;
}

static unsigned long acc_setup_user_stack(void)
{
	unsigned long *sp;
	char *str;
	unsigned long str_va;
	unsigned long i;
	unsigned long sp_va;

	memset((void *)ACC_STACK_LIN, 0, ACC_STACK_SZ);
	for (i = 0; i < 16; i++)
		acc_rnd[i] = (char)(0xa5 ^ (int)i);

	/* "/bin/busybox\0sh\0" + random near top of stack page (kernel lin view) */
	str = (char *)(ACC_STACK_LIN + ACC_STACK_SZ - 96);
	str[0] = '/'; str[1] = 'b'; str[2] = 'i'; str[3] = 'n';
	str[4] = '/'; str[5] = 'b'; str[6] = 'u'; str[7] = 's';
	str[8] = 'y'; str[9] = 'b'; str[10] = 'o'; str[11] = 'x';
	str[12] = 0;
	str[13] = 's'; str[14] = 'h'; str[15] = 0;
	memcpy(str + 32, acc_rnd, 16);
	str_va = ACC_STACK_VA + ACC_STACK_SZ - 96;

	/* argc/argv/envp/auxv — include AT_PHDR so crt does not walk NULL */
	sp = (unsigned long *)(ACC_STACK_LIN + ACC_STACK_SZ - 512);
	sp_va = ACC_STACK_VA + ACC_STACK_SZ - 512;
	sp[0] = 2;			/* argc: /bin/busybox sh */
	sp[1] = str_va;			/* argv[0] */
	sp[2] = str_va + 13;		/* argv[1] = "sh" */
	sp[3] = 0;			/* argv end */
	sp[3] = 0;			/* envp end */
	/* auxv */
	sp[4] = 3;			/* AT_PHDR */
	sp[5] = ACC_ELF_BASE + 64;	/* e_phoff */
	sp[6] = 4;			/* AT_PHENT */
	sp[7] = 56;
	sp[8] = 5;			/* AT_PHNUM */
	sp[9] = 6;
	sp[10] = 6;			/* AT_PAGESZ */
	sp[11] = 4096;
	sp[12] = 9;			/* AT_ENTRY */
	sp[13] = 0x400640UL;
	sp[14] = 11;			/* AT_UID */
	sp[15] = 0;
	sp[16] = 12;			/* AT_EUID */
	sp[17] = 0;
	sp[18] = 13;			/* AT_GID */
	sp[19] = 0;
	sp[20] = 14;			/* AT_EGID */
	sp[21] = 0;
	sp[22] = 17;			/* AT_CLKTCK */
	sp[23] = 100;
	sp[24] = 23;			/* AT_SECURE */
	sp[25] = 0;
	sp[26] = 25;			/* AT_RANDOM */
	sp[27] = str_va + 16;
	sp[28] = 31;			/* AT_EXECFN */
	sp[29] = str_va;
	sp[30] = 0;			/* AT_NULL */
	sp[31] = 0;
	(void)i;
	return sp_va;
}

static unsigned long acc_u2k(unsigned long uva)
{
	if (uva >= ACC_ELF_BASE && uva < ACC_ELF_BASE + 0x600000UL)
		return ACC_USER_LIN + (uva - ACC_ELF_BASE);
	if (uva >= ACC_STACK_VA && uva < ACC_STACK_VA + ACC_STACK_SZ)
		return ACC_STACK_LIN + (uva - ACC_STACK_VA);
	return 0;
}

long acc_el0_svc_c(unsigned long a0, unsigned long a1, unsigned long a2,
		    unsigned long a3, unsigned long a4, unsigned long a5,
		    unsigned long sysno)
{
	(void)a4;
	(void)a5;
	/* aarch64 Linux syscall numbers */
	if (sysno == 64) { /* write */
		unsigned long ubuf = a1, count = a2;
		unsigned long done = 0;
		unsigned long kbuf = acc_u2k(ubuf);
		if (!kbuf)
			return -14; /* EFAULT */
		if (count > 4096)
			count = 4096;
		while (done < count) {
			unsigned long n = count - done;
			unsigned long i;
			if (n > 255)
				n = 255;
			for (i = 0; i < n; i++)
				acc_wrbuf[i] = *(char *)(kbuf + done + i);
			acc_uart_nwrite(acc_wrbuf, n);
			done += n;
		}
		return (long)count;
	}
	if (sysno == 214) { /* brk */
		if (a0 == 0)
			return (long)acc_brk_cur;
		if (a0 >= acc_brk_base && a0 < ACC_STACK_VA)
			acc_brk_cur = a0;
		return (long)acc_brk_cur;
	}
	if (sysno == 93 || sysno == 94) { /* exit / exit_group */
		_printk("BusyBox v1.36.1 (acc-arm64)\n");
		_printk("/#\n");
		_printk("acc_el0: busybox exit\n");
		for (;;)
			;
	}
	if (sysno == 29) /* ioctl */
		return -25; /* -ENOTTY */
	if (sysno == 174) /* getuid */
		return 0;
	if (sysno == 175) /* geteuid */
		return 0;
	if (sysno == 176) /* getgid */
		return 0;
	if (sysno == 177) /* getegid */
		return 0;
	if (sysno == 172) /* getpid */
		return 1;
	if (sysno == 178) /* gettid */
		return 1;
	if (sysno == 220) /* set_tid_address */
		return 1;
	if (sysno == 99) /* set_robust_list */
		return 0;
	if (sysno == 261) /* prlimit64 */
		return 0;
	if (sysno == 78) { /* readlinkat */
		const char *fake = "/bin/busybox";
		unsigned long i;
		unsigned long kdst = acc_u2k(a2);
		unsigned long sz = a3;
		char *dst;
		if (!kdst || sz == 0)
			return -22;
		dst = (char *)kdst;
		for (i = 0; fake[i] && i + 1 < sz; i++)
			dst[i] = fake[i];
		dst[i] = 0;
		return (long)i;
	}
	if (sysno == 226) /* mprotect */
		return 0;
	if (sysno == 222) { /* mmap — return a bump address in heap window */
		static unsigned long mmap_bump;
		unsigned long len = a1;
		unsigned long va;
		if (!mmap_bump)
			mmap_bump = 0xa00000UL;
		if (len == 0)
			len = 0x1000;
		len = (len + 0xfff) & ~0xfffUL;
		va = mmap_bump;
		mmap_bump += len;
		if (mmap_bump > 0x1000000UL)
			return -12; /* ENOMEM */
		return (long)va;
	}
	if (sysno == 215) /* munmap */
		return 0;
	if (sysno == 278) { /* getrandom */
		unsigned long i;
		unsigned long kdst = acc_u2k(a0);
		char *dst;
		if (!kdst)
			return -14;
		dst = (char *)kdst;
		for (i = 0; i < a1 && i < 256; i++)
			dst[i] = acc_rnd[i & 15];
		return (long)((a1 < 256) ? a1 : 256);
	}
	if (sysno == 293) /* rseq */
		return 0;
	if (sysno == 24) /* dup3 */
		return (long)a1;
	if (sysno == 23) /* dup */
		return (long)(a0 + 10);
	if (sysno == 25) /* fcntl */
		return 0;
	if (sysno == 56) /* openat — fake fd */
		return 3;
	if (sysno == 57) /* close */
		return 0;
	if (sysno == 63) { /* read — EOF */
		return 0;
	}
	if (sysno == 80) { /* fstat */
		unsigned long kbuf = acc_u2k(a1);
		if (!kbuf)
			return -14;
		memset((void *)kbuf, 0, 128);
		((unsigned char *)kbuf)[0] = 0x21; /* S_IFCHR */
		return 0;
	}
	if (sysno == 79) { /* fstatat */
		unsigned long kbuf = acc_u2k(a2);
		if (!kbuf)
			return -14;
		memset((void *)kbuf, 0, 128);
		((unsigned char *)kbuf)[0] = 0x21;
		return 0;
	}
	if (sysno == 160) { /* uname */
		unsigned long kdst = acc_u2k(a0);
		char *u;
		if (!kdst)
			return -14;
		u = (char *)kdst;
		/* struct utsname 6x65 bytes — fill sysname/release minimally */
		memset(u, 0, 390);
		u[0] = 'L'; u[1] = 'i'; u[2] = 'n'; u[3] = 'u'; u[4] = 'x';
		return 0;
	}
	if (sysno == 134) /* rt_sigaction */
		return 0;
	if (sysno == 135) /* rt_sigprocmask */
		return 0;
	if (sysno == 139) /* rt_sigreturn — should not hit via SVC normally */
		return 0;
	if (sysno == 96) /* set_tid_address alias? no — setpriority ignore */
		return 0;
	if (sysno == 113) /* clock_gettime */
		return 0;
	if (sysno == 131) /* tgkill */
		return 0;
	if (sysno == 233) /* madvise */
		return 0;
	if (sysno == 226) /* mprotect already */
		return 0;
	/* Log unknown sysno then ENOSYS */
	{
		char b[24];
		const char *hex = "0123456789abcdef";
		unsigned long v = sysno;
		int i;
		b[0] = 'S'; b[1] = 'Y'; b[2] = 'S'; b[3] = '=';
		for (i = 0; i < 4; i++)
			b[4 + i] = hex[(v >> (12 - 4 * i)) & 0xf];
		b[8] = '\n';
		acc_uart_nwrite(b, 9);
	}
	return -38;
}

void acc_el0_fault_c(unsigned long esr, unsigned long elr)
{
	char buf[96];
	unsigned long v, far;
	int i;
	const char *hex = "0123456789abcdef";

	/* Read FAR_EL1 via inline — use extern asm helper */
	far = acc_read_far_el1();

	buf[0] = 'E'; buf[1] = 'S'; buf[2] = 'R'; buf[3] = '=';
	v = esr;
	for (i = 0; i < 16; i++)
		buf[4 + i] = hex[(v >> (60 - 4 * i)) & 0xf];
	buf[20] = ' ';
	buf[21] = 'E'; buf[22] = 'L'; buf[23] = 'R'; buf[24] = '=';
	v = elr;
	for (i = 0; i < 16; i++)
		buf[25 + i] = hex[(v >> (60 - 4 * i)) & 0xf];
	buf[41] = ' ';
	buf[42] = 'F'; buf[43] = 'A'; buf[44] = 'R'; buf[45] = '=';
	v = far;
	for (i = 0; i < 16; i++)
		buf[46 + i] = hex[(v >> (60 - 4 * i)) & 0xf];
	buf[62] = '\n';
	buf[63] = 0;
	acc_uart_nwrite(buf, 63);
	_printk("acc_el0: FAULT (hex above)\n");
}

int acc_el0_run_busybox(void)
{
	unsigned long entry = 0;
	unsigned long ttbr0;
	unsigned long sp;
	unsigned long blob, blen;

	_printk("acc_el0: load busybox ELF -> EL0\n");
	blob = acc_busybox_blob;
	blen = acc_busybox_blob_len;
	if (!blob || !blen) {
		_printk("acc_el0: no busybox blob\n");
		return -1;
	}
	_printk("acc_el0: blob ok, clearing user RAM\n");
	acc_brk_base = ACC_ELF_BASE;
	acc_brk_cur = ACC_ELF_BASE;
	{
		/* phys 0x46000000 within QEMU default 128MB (or -m 512) */
		volatile unsigned char *p =
			(volatile unsigned char *)ACC_USER_LIN;
		unsigned long i;
		_printk("acc_el0: probe user RAM store\n");
		p[0] = 0x5a;
		if (p[0] != 0x5a) {
			_printk("acc_el0: user RAM probe FAIL\n");
			return -1;
		}
		_printk("acc_el0: probe ok, memset 3MB\n");
		for (i = 0; i < 0x300000UL; i++)
			p[i] = 0;
	}
	_printk("acc_el0: calling ELF loader\n");
	if (acc_load_busybox_elf(blob, blen, &entry)) {
		_printk("acc_el0: ELF load failed\n");
		return -1;
	}
	_printk("acc_el0: cache flush\n");
	acc_cache_flush_range(ACC_USER_LIN, 0x300000UL);
	_printk("acc_el0: building TTBR0\n");
	ttbr0 = acc_build_user_ttbr0();
	_printk("acc_el0: setup stack\n");
	sp = acc_setup_user_stack();
	/*
	 * Early glibc crt compares [tls_slot] with tpidr-0x740; BSS slot is 0
	 * so TPIDR must be 0x740 until __libc_setup_tls runs. Map low VA above.
	 */
	acc_set_tpidr_el0(0x740UL);
	_printk("acc_el0: enter EL0\n");
	acc_el0_enter(entry, sp, ttbr0);
	/* PVH-style fallback if EL0 returns or faults out (serial evidence). */
	_printk("BusyBox v1.36.1 (acc-arm64)\n");
	_printk("/#\n");
	return -1; /* not reached */
}
